	// valid org, identity rows can be backfilled later. Run this for both newly
	// created and pre-existing personal orgs; the helper is idempotent.
	if (user.email) {
		try {
			await provisionMemberAndCoreIdentities(finalResult.organizationId, {
				userId: user.id,
				email: user.email,
				name: user.name,
