/**
 * Install-operator bootstrap.
 *
 * At first `lobu run` boot, this provisions a synthetic `install_operator`
 * user so headless installs (CI, containers, /tmp scaffolds without a
 * browser) can sign in via better-auth without a chicken-and-egg /sign-up
 * step. The operator's password is the install's `ENCRYPTION_KEY` —
 * already in `.env` for at-rest encryption, now doing double duty as the
 * install secret. See `docs/plans/install-operator-bootstrap.md` for the full
 * design.
 *
 * Idempotent. Safe to call on every boot.
 */

import { hostname } from 'node:os';
import { hashPassword } from 'better-auth/crypto';
import { assertEncryptionKey } from '@lobu/core';
import { getDb } from '../db/client';
import { ensureBuilderAgent } from './builder-provisioning';
import { generateSecureToken } from './oauth/utils';
import { ensurePersonalOrganization } from './personal-org-provisioning';

export const INSTALL_OPERATOR_KIND = 'install_operator' as const;

/**
 * Deterministic synthetic email for the install operator. Not a real
 * deliverable address — no password reset / magic link will ever reach
 * it (and the carve-outs in `auth/index.tsx` reject those flows
 * anyway). Using `<hostname>` keeps it stable across reboots on the
 * same host; falls back to `localhost` when `hostname()` is empty.
 */
function installOperatorEmail(): string {
  return `install@${hostname() || 'localhost'}`.toLowerCase();
}

/**
 * Provision the install operator user + credential account + personal
 * org if they don't yet exist. Idempotent.
 *
 * Returns the operator user id (whether it existed or was just created)
 * so callers can chain `ensureDefaultAgent` etc. against the operator's
 * personal org if they want to.
 */
export async function ensureInstallOperator(): Promise<{
  userId: string;
  created: boolean;
}> {
  const encryptionKey = process.env.ENCRYPTION_KEY;
  if (!encryptionKey) {
    throw new Error(
      'ensureInstallOperator: ENCRYPTION_KEY is required. Set it in .env or opt into ephemeral keys with LOBU_ALLOW_EPHEMERAL_ENCRYPTION_KEY=1 (which gateway.ts will generate before this is called).'
    );
  }
  // Validate shape NOW, not later. `hashPassword` happily accepts any
  // string, so a malformed key would bootstrap the operator fine — but
  // then every encrypt/decrypt call (saving a provider API key, etc.)
  // would 500 with the same canonical message. Fail at install instead
  // of leaving a half-broken operator that can sign in but can't
  // persist any encrypted secret.
  assertEncryptionKey(encryptionKey);

  const sql = getDb();

  // Convergent provisioning: every boot ensures each step exists. The
  // user/account rows are immutable (we never re-hash on top of an
  // existing password — that would silently rotate credentials when
  // ENCRYPTION_KEY changed). But the personal-org step lives outside
  // the user-creation txn, so a transient failure there used to leave
  // the operator permanently broken: subsequent boots would see the
  // user row and skip provisioning entirely, and `/api/local-init`
  // would loop forever on `personal_org_missing`. Now we check each
  // step independently and patch missing pieces.
  const existing = (await sql`
    SELECT id FROM "user"
     WHERE principal_kind = ${INSTALL_OPERATOR_KIND}
     LIMIT 1
  `) as unknown as Array<{ id: string }>;

  let userId: string;
  let created: boolean;

  if (existing.length > 0) {
    userId = existing[0]!.id;
    created = false;
  } else {
    userId = `user_install_${generateSecureToken(8)}`;
    const email = installOperatorEmail();
    const hashed = await hashPassword(encryptionKey);

    await sql.begin(async (tx) => {
      await tx`
        INSERT INTO "user"
          (id, name, email, "emailVerified", principal_kind, "createdAt", "updatedAt")
        VALUES
          (${userId}, ${'Local Install'}, ${email}, true,
           ${INSTALL_OPERATOR_KIND}, NOW(), NOW())
      `;

      // Better Auth's email-password adapter expects one `account` row
      // per user with providerId='credential' and the hashed password
      // stored in the `password` column. accountId matches userId by
      // convention.
      const accountId = `acct_install_${generateSecureToken(8)}`;
      await tx`
        INSERT INTO "account"
          (id, "accountId", "providerId", "userId", password,
           "createdAt", "updatedAt")
        VALUES
          (${accountId}, ${userId}, 'credential', ${userId}, ${hashed},
           NOW(), NOW())
      `;
    });
    created = true;
  }

  // Personal org provisioning is convergent: ensurePersonalOrganization
  // is itself idempotent (returns the existing org if one is already
  // tagged with this user.id in metadata). Running it on every boot
  // closes the gap where a transient failure on first boot used to
  // leave the operator without a personal org forever.
  try {
    const personalOrg = await ensurePersonalOrganization({
      id: userId,
      email: installOperatorEmail(),
      name: 'Local Install',
      username: null,
    });
    // Builder (system) agent for the operator's personal org. Idempotent
    // (sentinel-guarded) and best-effort — never break the boot path.
    await ensureBuilderAgent(personalOrg.organizationId);
  } catch (err) {
    console.error(
      '[install-operator] Personal-org provisioning failed; will retry on next boot:',
      err
    );
  }

  return { userId, created };
}
/**
 * Local-install bootstrap hooks — shared by BOTH `lobu run` backends:
 *
 *   - embedded Postgres (`embedded-runtime.ts`), always;
 *   - external postgres:// DATABASE_URL (`server.ts`), only when the CLI set
 *     LOBU_RUN_OWNS_DB=1.
 *
 * The hooks provision the synthetic `install_operator` user (+ its personal
 * org) and the default agent, so a fresh install is sign-in-able via
 * `/api/local-init` without a chicken-and-egg /sign-up. Both steps are
 * idempotent and never crash boot. They must run as pre-listen hooks: the
 * gateway init that precedes them establishes ENCRYPTION_KEY, which
 * `ensureInstallOperator` requires.
 *
 * 🚨 SAFETY INVARIANT — cloud/multi-replica prod must NEVER auto-provision
 * users or orgs. `LOBU_RUN_OWNS_DB=1` is set in exactly one place: the CLI's
 * `lobu run` command (`packages/cli/src/commands/dev.ts`) when it spawns the
 * server bundle for a single-operator local install. The prod chart
 * (`charts/lobu`) and deployment manifests never set it, so
 * `externalDbBootstrapHooks` returns `[]` there and prod boots stay
 * bootstrap-free. Do not gate bootstrap on anything weaker than this explicit
 * opt-in flag, and never set the flag from inside the server.
 */

import postgres from "postgres";
import { ensureBuilderAgent } from "./auth/builder-provisioning";
import { ensureDefaultAgent } from "./auth/default-provisioning";
import { ensureInstallOperator } from "./auth/install-operator";
import logger from "./utils/logger";

type PreListenHook = () => Promise<void> | void;

/**
 * The two local-install provisioning hooks, in order. `databaseUrl` must be
 * the final resolved postgres:// URL (embedded: the spawned cluster's TCP
 * URL; external: DATABASE_URL itself).
 */
export function buildLocalBootstrapHooks(databaseUrl: string): PreListenHook[] {
	return [
		// BEFORE listen so headless installs (CI, containers) sign in via
		// better-auth without a chicken-and-egg /sign-up. Provisions the
		// synthetic `install_operator` user; idempotent. Never crash boot.
		async () => {
			try {
				await ensureInstallOperator();
			} catch (err) {
				logger.error({ err }, "Install-operator provisioning failed");
			}
		},
		// Default-agent provisioning: resolve the personal org id each boot so
		// a returning user picks up the default agent.
		async () => {
			try {
				const rows = postgres(databaseUrl, { max: 1 });
				try {
					const orgs = (await rows`
            SELECT id FROM "organization"
            WHERE (metadata::jsonb)->>'personal_org_for_user_id' IS NOT NULL
            ORDER BY "createdAt" ASC LIMIT 1
          `) as unknown as Array<{ id: string }>;
					const orgId = orgs[0]?.id ?? null;
					if (orgId) {
						await ensureDefaultAgent(orgId);
						await ensureBuilderAgent(orgId);
					}
				} finally {
					await rows.end({ timeout: 1 });
				}
			} catch (err) {
				logger.warn({ err }, "Default-agent provisioning failed");
			}
		},
	];
}

/**
 * Flag-gated bootstrap for the external-DATABASE_URL branch. Returns the
 * bootstrap hooks ONLY when `LOBU_RUN_OWNS_DB === "1"` (the CLI-owned local
 * install marker — see the safety invariant above); otherwise `[]`, which is
 * what every cloud/prod deployment gets.
 */
export function externalDbBootstrapHooks(
	databaseUrl: string,
	env: NodeJS.ProcessEnv,
): PreListenHook[] {
	if (env.LOBU_RUN_OWNS_DB !== "1") return [];
	return buildLocalBootstrapHooks(databaseUrl);
}
/**
 * Shared server lifecycle spine.
 *
 * `server.ts` is the single entry for both backends (external Postgres and
 * local embedded Postgres); it calls into `createServerLifecycle()` so
 * middleware ordering, route mounts,
 * httpServer timeouts, shutdown sequence, and signal wiring stay identical
 * by construction. Drift between the two modes was the root cause of #948;
 * the only way to express a per-mode difference now is the four named hooks
 * on `ServerLifecycleConfig`.
 *
 * Do not add `new Hono`, `app.use`, `app.route`, `http.createServer`, or
 * `process.on('SIGTERM' | 'SIGINT', …)` to either entry — they belong here.
 */

import http from "node:http";
import v8 from "node:v8";
