	const { pathname, search } = useLocation();
	const searchRecord = (search ?? {}) as Record<string, unknown>;
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	// The Builder (system agent) is shown FIRST in the Agents roster (via
	// rosterAgents). Click an agent → chat; expand for configuration destinations.
	const { rosterAgents, systemAgentId, isLoading } = useWorkingAgents();
	const rosterAgentIds = useMemo(
		() => rosterAgents.map((agent) => agent.agentId),
		[rosterAgents],
	);
	const { threads: recentThreads } = useRecentAgentThreads(
		owner,
		rosterAgentIds,
		{
			enabled: !!owner && rosterAgentIds.length > 0,
			limit: RECENT_THREAD_LIMIT,
		},
	);
	const { data: mcpConversations = [] } = useClientActivityScopes({
		enabled: !!owner,
		limit: RECENT_THREAD_LIMIT,
		activityKind: "conversation",
		excludeCommandClients: true,
	});
	const { data: connectedClients = [] } = useConnectedClients(null, {
		enabled: !!owner,
	});
	const connectedAppGroups = useMemo(
		() => groupClients(connectedClients).filter((group) => group.connected),
