function NavRow({
	to,
	params,
	search,
	active,
	icon: Icon,
	leading,
	label,
	detail,
	trailing,
	lastActivityAt,
}: {
	to?: string;
	params?: Record<string, string>;
	search?: Record<string, unknown>;
	active: boolean;
	icon?: IconComponent;
	/** Custom leading glyph (e.g. EntityIcon). Wins over `icon` when set. */
	leading?: ReactNode;
	label: string;
	/** Context shown below a Recent title, before its relative activity time. */
	detail?: string;
	/** Right-aligned adornment (e.g. a record count). */
	trailing?: ReactNode;
	lastActivityAt?: number;
}) {
	const isRecent = lastActivityAt != null;
	const metadata = isRecent
		? [detail?.trim(), formatTimeAgo(lastActivityAt)]
				.filter(Boolean)
				.join(" · ")
		: null;
	const content = isRecent ? (
		<>
			<span className="block truncate text-sm">{label}</span>
			<span className="mt-0.5 flex min-w-0 items-center gap-1.5 text-xs text-sidebar-foreground/50">
				<span className="flex h-3.5 w-3.5 shrink-0 items-center justify-center">
					{leading ?? (Icon ? <Icon className="h-3.5 w-3.5" /> : null)}
				</span>
				<span className="truncate">{metadata}</span>
			</span>
		</>
	) : (
		<>
			<span className="flex h-3.5 w-3.5 shrink-0 items-center justify-center text-sidebar-foreground/60">
				{leading ?? (Icon ? <Icon className="h-3.5 w-3.5" /> : null)}
			</span>
			<span className="min-w-0 flex-1 truncate">{label}</span>
			{trailing}
		</>
	);
	const rowClassName = cn(
		"mx-2 rounded-md text-sm transition-colors",
		isRecent ? "block px-3 py-2" : "flex items-center gap-2 py-1.5 pl-3 pr-3",
		active
			? "bg-sidebar-accent text-sidebar-accent-foreground"
			: to
				? "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
				: "text-sidebar-foreground/80",
	);
	if (!to) {
		return (
			<div data-recent-row={isRecent ? "" : undefined} className={rowClassName}>
				{content}
			</div>
		);
	}
	return (
		<Link
			to={to as "/"}
			params={params as never}
			search={search as never}
			aria-label={isRecent ? label : undefined}
			title={isRecent ? undefined : label}
			data-recent-row={isRecent ? "" : undefined}
			className={rowClassName}
		>
			{content}
		</Link>
	);
}

/**
 * Collapse override for a route-driven collapsible: the route decides the
 * default (active ⇒ open), a manual toggle wins until the route context
 * changes again. Implemented with the render-time state-reset idiom so a
 * navigation into/out of the group re-applies the route default.
 */
function useRouteDefaultOpen(routeActive: boolean): {
	open: boolean;
	setOpen: (open: boolean) => void;
} {
	const [override, setOverride] = useState<boolean | null>(null);
	const [lastRouteActive, setLastRouteActive] = useState(routeActive);
	if (routeActive !== lastRouteActive) {
		setLastRouteActive(routeActive);
		setOverride(null);
	}
	return { open: override ?? routeActive, setOpen: setOverride };
}

