const logger = createLogger("orchestrator");

/**
 * Mint the per-run worker JWT the worker uses as its PRIMARY gateway auth
 * (`session-runner`: `runJobToken || WORKER_TOKEN`). Extracted as a pure,
 * exported function so the claim set is exercised by a regression test that
 * pins parity with the consumer requirements — the #1274 P0 (this mint
 * omitted `connectionId`, so every chat `ask_user` 500'd at
 * `assertRoutableInteraction`) shipped precisely because no test drove the
 * mint code. Any claim a downstream consumer reads off the verified worker
 * token (connectionId, source, platform, teamId, agentId, organizationId,
 * runId, …) MUST be set here; the test asserts that so the next omitted
 * claim fails red instead of in prod.
 */
/**
 * Internal admin tools the org's builder agent may call from its worker. The
 * grant rides the per-run worker token (set in `resolveBuilderAdminGrant` only
 * for the system agent on an owner/admin-initiated turn) and is enforced
 * tool-by-tool at the execute gate. Keep this in lockstep with the gate's
 * exact-name check in `tools/execute.ts`.
 */
export const BUILDER_ADMIN_TOOLS = [
  "manage_agents",
  "manage_connections",
  "manage_feeds",
  "manage_behaviors",
  "manage_schedules",
  "manage_entity",
] as const;

/** Builder admin allowlist paired with the Lobu auth user it was resolved for. */
export interface BuilderAdminGrant {
  tools: string[];
  /** Lobu auth user resolved from the turn's platform principal. */
  actorUserId: string;
}

/**
 * Decide whether THIS turn's worker token should carry the builder admin-tool
 * grant. Returns the allowlist and resolved Lobu auth actor only when the target
 * agent is the org's system agent (`organization.system_agent_id`) AND the
 * human sending the message is an org owner/admin. Fails closed (returns
 * undefined) on any lookup error — a missing grant just means the model can't
 * see/call the admin tools, never an over-grant. One indexed query (org PK +
 * member join); runs per turn.
 */
export async function resolveBuilderAdminGrant(args: {
  agentId?: string;
  organizationId?: string;
  userId?: string;
  /**
   * Platform this turn originated from. On a chat platform (slack/telegram/…)
   * `userId` is the PLATFORM user id (e.g. Slack `U…`), NOT a Lobu user id, so
   * the member lookup below would never match and an org owner driving the
   * builder from Slack would silently lose the admin grant. We resolve the
   * platform id → linked Lobu user first. Absent / "api" → `userId` is already
   * the session's Lobu user id and is used directly.
   */
  platform?: string;
  /**
   * Workspace team id for identity lookup (Slack `T…` from the event). Prefer
   * this over routing keys; see call site for platformMetadata.teamId.
   */
  teamId?: string;
  /**
   * Optional second team key to try when the first miss (e.g. Slack connection
   * `external_tenant_id` = Grid enterprise `E…` while the event carries a
   * workspace `T…`). Only an exact row under that key counts — never a
   * cross-team unique-user collapse.
   */
  alternateTeamId?: string;
}): Promise<BuilderAdminGrant | undefined> {
  if (!args.agentId || !args.organizationId || !args.userId) return undefined;
  try {
    // Map a platform user id to its linked Lobu user before the member join.
    // resolveChatUserIdentity is workspace-scoped (the identity key is the
    // composite TEAM:USER) and returns null when the id isn't linked, so a
    // grant is only ever made for a linked, known user.
    const platform = args.platform;
    const isChatPlatform =
      platform != null && platform !== "api" && platform !== "";
    let lobuUserId: string | null | undefined = isChatPlatform
      ? await resolveChatUserIdentity(platform, args.teamId, args.userId)
      : args.userId;
    if (
      !lobuUserId &&
      isChatPlatform &&
      args.alternateTeamId &&
      args.alternateTeamId !== args.teamId
    ) {
      lobuUserId = await resolveChatUserIdentity(
        platform,
        args.alternateTeamId,
        args.userId,
      );
    }
    if (!lobuUserId) return undefined;
    const sql = getDb();
    const rows = (await sql`
      SELECT o.system_agent_id, m.role
      FROM organization o
      LEFT JOIN "member" m
        ON m."organizationId" = o.id AND m."userId" = ${lobuUserId}
      WHERE o.id = ${args.organizationId}
      LIMIT 1
    `) as unknown as Array<{ system_agent_id: string | null; role: string | null }>;
    const row = rows[0];
    if (!row || row.system_agent_id !== args.agentId) return undefined;
    if (row.role !== "owner" && row.role !== "admin") return undefined;
    return { tools: [...BUILDER_ADMIN_TOOLS], actorUserId: lobuUserId };
  } catch (err) {
    logger.warn(
      { err, organizationId: args.organizationId, agentId: args.agentId },
      "resolveBuilderAdminGrant failed; minting without admin grant"
    );
    return undefined;
  }
}

/**
 * The two team keys the Builder admin grant is looked up under, derived from a
 * message payload. Extracted from the dispatch path so the
 * metadata→tenant→grant composition is testable on its own — the pieces
 * (identity link, tenant store, grant) each had coverage, but the wiring
 * between them did not, and that is precisely where a runtime-id-vs-slug
 * mismatch silently disables the grant for BYO connections.
 *
 * - `teamId`: the real workspace/enterprise id from `platformMetadata` (T… /
 *   E…). `routingTeamId` is a ROUTING key (platform name for DMs, channel id
 *   for groups — see message-handler-bridge `payloadTeamId`), NOT a workspace
 *   id, so it is only the fallback that keeps non-Slack callers working.
 * - `alternateTeamId`: Grid enterprise installs key connections + some identity
 *   rows on E… while events carry the workspace T…. The connection's tenant is
 *   offered as an exact second key only — never a global U… collapse — and is
          conversationId: effectiveConversationId,
          threadId,
          kind,
          userId: data.userId,
          title: data.messageText?.slice(0, 200) || null,
          isDirect,
          locationLabel,
          lastActivityAt: new Date(),
        });
      }

      const canonicalConversationKey = buildCanonicalConversationKey({
        organizationId: data.organizationId,
        agentId: data.agentId,
        platform: data.platform,
        channelId: data.channelId,
        conversationId: effectiveConversationId,
      });
      const deploymentName = generateDeploymentName({
        organizationId: data.organizationId,
        agentId: data.agentId,
        userId: data.userId,
        platform: data.platform,
        channelId: data.channelId,
        conversationId: effectiveConversationId,
      });

      // Mint a per-run worker JWT bound to this exact `runs.id` and pass
      // it to the worker via the message payload. The snapshot route uses
      // it to enforce `tokenData.runId === body.runId`, so a worker
      // bearing a same-(org, agent, conv) deployment-lifetime token
      // cannot POST under a different run's slot. Codex round 2 finding
      // A on PR #865. Every dispatch is bound to its claimed runs.id.
      // Builder admin-tool grant: only the org's system agent, only when the
      // human driving this turn is an owner/admin. Fails closed.
      //
      const { teamId: workspaceTeamId, alternateTeamId } =
        await resolveGrantTeamKeys({
          platform: data.platform,
          organizationId: data.organizationId,
          routingTeamId: data.teamId,
          platformMetadata: data.platformMetadata,
        });
      const adminGrant = await resolveBuilderAdminGrant({
        agentId: data.agentId,
        organizationId: data.organizationId,
        userId: data.userId,
        platform: data.platform,
        teamId: workspaceTeamId,
        alternateTeamId,
      });

      // Resolve THIS CONVERSATION's pinned runtime provider from its sandbox.
      // The pin is frozen on the first turn and read thereafter, so an agent
      // repoint never moves an existing conversation's sandbox. Undefined →
      // local just-bash.
      //
      // Best-effort at the enqueue site: resolvePinnedSelection throws on a total
      // DB failure (to fail-closed the RUNTIME realm decision), but dispatch
      // liveness must not hinge on a pin read — a blip here degrades this ONE turn
      // to unpinned rather than dropping the message. The pin self-heals on the
      // next turn (the CAS guard means an unpinned dispatch never overwrites an
      // existing pin), and the runtime route re-resolves the realm from the token.
      let runtimeSelection: Awaited<ReturnType<typeof resolvePinnedSelection>>;
      try {
        runtimeSelection = await resolvePinnedSelection({
          organizationId: data.organizationId,
          agentId: data.agentId,
          platform: data.platform,
          conversationId: effectiveConversationId,
        });
      } catch (err) {
        logger.warn(
          { traceId, agentId: data.agentId, error: getErrorMessage(err) },
          "Pin resolution failed at enqueue; dispatching this turn unpinned"
        );
        runtimeSelection = {};
      }

      // Stamp the pinned provider onto the payload body so the worker selects its
      // bash backend per-turn (a warm deployment is reused across conversations
			messageCount++;
			if (entry.message.role === "user") userMessages++;
			if (entry.message.role === "assistant") assistantMessages++;
			if (entry.message.usage) {
				const u = entry.message.usage as {
					inputTokens?: number;
					input?: number;
					outputTokens?: number;
					output?: number;
				};
				totalInputTokens += u.inputTokens || u.input || 0;
				totalOutputTokens += u.outputTokens || u.output || 0;
			}
		}
		if (entry.type === "model_change") {
			currentModel = `${entry.provider}/${entry.modelId}`;
		}
	}

	return {
		sessionId: sessionId || "unknown",
		messageCount,
		userMessages,
		assistantMessages,
		totalInputTokens,
		totalOutputTokens,
		currentModel,
	};
}

export function createAgentHistoryRoutes(deps: {
	connectionManager?: WorkerConnectionManager;
	agentConfigStore?: Pick<AgentConfigStore, "getMetadata">;
	userAgentsStore?: UserAgentsStore;
	artifactStore?: ArtifactStore;
	publicGatewayUrl?: string;
}) {
	const app = new Hono();
	const { connectionManager, artifactStore, publicGatewayUrl } = deps;
	const resolveOwnership = createOwnershipResolver({
		userAgentsStore: deps.userAgentsStore,
		agentMetadataStore: deps.agentConfigStore,
	});

	async function canUseSystemAgent(
		agentId: string,
		organizationId: string,
		userId: string,
	): Promise<boolean> {
		const rows = await getDb()`
			SELECT 1
			FROM "organization" o
			JOIN "member" m ON m."organizationId" = o.id
			WHERE o.id = ${organizationId}
				AND o.system_agent_id = ${agentId}
				AND m."userId" = ${userId}
				AND m.role IN ('owner', 'admin')
			LIMIT 1
		`;
		return rows.length > 0;
	}

	async function getAuthorizedAgentScope(c: Context): Promise<{
		agentId: string;
		organizationId: string | undefined;
		userId: string;
		isAdmin: boolean;
	} | null> {
		const session = await verifySettingsSession(c);
		if (!session) return null;
		const agentId = c.req.param("agentId") || session.agentId || null;
		if (!agentId || !isSafeAgentId(agentId)) return null;
		const userId = resolveSettingsLookupUserId(session);
		const ambientOrgId = resolveOrgId();

		// Apply the resolver's admin bypass and agent-binding restriction before
		// selecting a tenant from the ambient request.
		if (session.isAdmin) {
			if (!ambientOrgId) return null;
			return {
				agentId,
				organizationId: ambientOrgId,
				userId,
				isAdmin: true,
			};
		}
		if (session.agentId && session.agentId !== agentId) return null;

		// The SPA sends x-lobu-org for the workspace being viewed. Its
		// membership-verified ambient org must win over ownership-first resolution
		// because the same system-agent id exists in every organization.
		if (ambientOrgId) {
			const ownsHere =
				(await deps.userAgentsStore?.ownsAgent(
					session.platform,
					userId,
					agentId,
					ambientOrgId,
				)) ?? false;
			const authorized =
				ownsHere || (await canUseSystemAgent(agentId, ambientOrgId, userId));
			if (authorized) {
				return {
					agentId,
					organizationId: ambientOrgId,
					userId,
					isAdmin: false,
				};
			}
			return null;
		}

		// History DB reads and worker/file fallbacks all require a proven tenant.
		// Metadata can be org-less here, so resolve the tenant independently from
		// the authoritative per-org owner mapping.
		const result = await resolveOwnership(session, agentId);
		if (!result.authorized) return null;
		const ownerOrganizations =
			await deps.userAgentsStore?.findAgentOrganizations(
				result.ownerPlatform ?? session.platform,
				result.ownerUserId ?? userId,
				agentId,
			);
		if (ownerOrganizations?.length !== 1) return null;
		return {
			agentId,
			organizationId: ownerOrganizations[0],
			userId,
			isAdmin: false,
		};
	}

	/**
	 * Platform transcripts belong to an org/channel audience, not only to the
	 * user who owns the agent. The outer Lobu middleware establishes this
	 * ambient org only after verifying Better Auth membership (and pins PATs),
	 * then the route intersects the agent's channel bindings with the source ACL.
	 * Agent owners retain the legacy bound-channel behavior; everyone else needs
	 * a fresh enforced ACL that proves channel membership.
	 * Keep the owner resolver above for every other history surface.
	 */
	async function getAuthorizedPlatformConversationScope(
		c: Context,
	): Promise<{
		agentId: string;
		organizationId: string;
		userId: string;
		allowNotGraphed: boolean;
		/**
		 * Platform admin. Distinct from `allowNotGraphed`, which an agent OWNER
		 * also gets: owning an agent must not confer read access to every user's
		 * private conversation with it.
		 */
		isAdmin: boolean;
	} | null> {
		const session = await verifySettingsSession(c);
		if (!session) return null;
		const agentId = c.req.param("agentId") || session.agentId || null;
		if (!agentId || !isSafeAgentId(agentId)) return null;
		const userId = resolveSettingsLookupUserId(session);

		// A shared system-agent id can resolve to an ownership row in another org.
		// Keep both the transcript lookup and owner check in the ambient org.
		const ambientOrgId = resolveOrgId();
		if (!ambientOrgId) return null;

		// Preserve the ownership resolver's platform-admin bypass, scoped to the
		// ambient org. Runs before the agent-binding check so an admin's request
		// isn't rejected by a session bound to another agent.
		if (session.isAdmin) {
			return {
				agentId,
				organizationId: ambientOrgId,
				userId,
				allowNotGraphed: true,
				isAdmin: true,
			};
		}
		if (session.agentId && session.agentId !== agentId) return null;

		const ownsHere =
			(await deps.userAgentsStore?.ownsAgent(
				session.platform,
				userId,
				agentId,
				ambientOrgId,
			)) ?? false;
		if (ownsHere) {
			return {
				agentId,
				organizationId: ambientOrgId,
				userId,
				allowNotGraphed: true,
				isAdmin: false,
			};
		}

		// `ownsAgent` reads `agent_users`, but legacy ownership can survive only
		// in agent metadata (`agents.owner_*`) that was never reconciled into the
		// mapping. Mirror the ownership resolver's metadata fallback so those
		// owners keep the legacy bound-channel path. `getMetadata` is ALS-scoped to
		// the ambient org, so a match proves ambient-org ownership: a per-org
		// SYSTEM agent (the Builder) has no per-user owner in a shared org (owner
		// column is NULL), so system-agent admins still fall through to the
		// enforced ACL below, unchanged. Reconcile into `agent_users` so the next
		// read hits the fast path.
		const metadata = await deps.agentConfigStore?.getMetadata(agentId);
		if (
			metadata?.owner &&
			metadata.organizationId === ambientOrgId &&
			sessionMatchesMetadataOwner(
				session,
				metadata.owner.platform,
				metadata.owner.userId,
			)
		) {
			deps.userAgentsStore
				?.addAgent(session.platform, userId, agentId, ambientOrgId)
				.catch(() => {
					/* best-effort reconciliation */
				});
			return {
				agentId,
				organizationId: ambientOrgId,
				userId,
				allowNotGraphed: true,
				isAdmin: false,
			};
		}

		return {
  responses: {
    200: { description: "Message queued", schema: SendMessageResponseSchema },
    ...errorResponses(ErrorResponseSchema, {
      400: "Invalid request",
      401: "Unauthorized",
      403: "Forbidden - worker tokens cannot route to platforms",
      404: "Agent not found",
    }),
  },
};

// =============================================================================
// System-agent resolution + gating
// =============================================================================

/**
 * Read `organization.system_agent_id` for the given org. Returns null when the
 * org has no row or no system agent set.
 */
async function getOrgSystemAgentId(
  organizationId: string
): Promise<string | null> {
  const rows = (await getDb()`
    SELECT system_agent_id FROM "organization" WHERE id = ${organizationId} LIMIT 1
  `) as unknown as Array<{ system_agent_id: string | null }>;
  return rows[0]?.system_agent_id ?? null;
}

/**
 * True when `userId` is an owner or admin of `organizationId`. Reuses the
 * `member` role check pattern shared by `organization-access.ts`.
 */
async function isOrgOwnerOrAdmin(
  organizationId: string,
  userId: string
): Promise<boolean> {
  const rows = (await getDb()`
    SELECT 1 FROM "member"
    WHERE "organizationId" = ${organizationId}
      AND "userId" = ${userId}
      AND role IN ('owner', 'admin')
    LIMIT 1
  `) as unknown as Array<unknown>;
  return rows.length > 0;
}

