// ============================================================
// Builder gate — approve / reject a held manage_agents write
// ============================================================
//
// The per-org builder agent's create/update/delete calls are server-gated:
// they produce a pending `runs` row + an approval card instead of mutating
// immediately. Approve/reject ride the SAME durable runs/events primitive that
// connector operations use, so they go through `manage_operations` (whose
// approve/reject handlers branch on the manage_agents run). The builder chat
// card (agent-thread `InteractiveToolPart`, via the interaction MCP App bridge)
// calls these.

export const useApproveAgentChange = createMutation<
	{ run_id: number },
	{ approved: true; run_id: number; event_id?: number; message: string }
>({
	tool: "manage_operations",
	body: (p) => ({ action: "approve", run_id: p.run_id }),
	invalidateKeys: [
		"agents",
		"system-agent-id",
		"notifications",
		"notifications-unread-count",
		"behavior-run-threads",
		// Refetch the config-prefill review query so an approved run resolves to
		// its 404 "no longer pending" state (re-enables the form) instead of
		// leaving a live Approve card on a run that's already applied.
		"pending-proposal",
	],
	successMessage: "Change approved — applying",
	invalidateOnError: true,
});

export const useRejectAgentChange = createMutation<
	{ run_id: number; reason?: string },
	{ rejected: true; run_id: number; event_id?: number }
>({
	tool: "manage_operations",
	body: (p) => ({
		action: "reject",
		run_id: p.run_id,
		...(p.reason ? { reason: p.reason } : {}),
	}),
	invalidateKeys: [
		"agents",
		"system-agent-id",
		"notifications",
		"notifications-unread-count",
		"behavior-run-threads",
		"pending-proposal",
	],
	successMessage: "Change rejected",
	invalidateOnError: true,
});

