        const provisioningOrgId = upserted[0].organization_id;
        const provisioningDeviceId = upserted[0].id;
        try {
          const isCandidateOrg = await hasOrgSentinel(
            provisioningOrgId,
            DEFAULT_AGENT_SENTINEL,
            sql
          );
          if (isCandidateOrg) {
