      // whole fleet currently advertises: auto-wire / re-activate the ones that
      // are present (cheap fast path, also heals partially-wired state), pause
      // the ones that have gone away. The just-upserted row above is already
      // visible to this query, so the polling device's capabilities count.
      await reconcileDeviceCapabilities(registrationUserId);
    } catch (err) {
      logger.error(
        { worker_id, err: errorMessage(err) },
        '[pollWorkerJob] device_workers upsert failed (non-fatal)'
      );
    }
    if (!deviceWorkerId) {
      try {
        const existing = (await sql`
          SELECT id FROM device_workers
          WHERE user_id = ${registrationUserId} AND worker_id = ${worker_id}
          LIMIT 1
        `) as unknown as Array<{ id: string }>;
        deviceWorkerId = existing[0]?.id ?? null;
      } catch (err) {
        logger.error(
          { worker_id, err: errorMessage(err) },
          '[pollWorkerJob] deviceWorkerId fallback lookup failed (non-fatal)'
        );
      }

		}
		providersMap.set((r as any).id, [...set]);
	}

	return c.json({
		agents: agents.map((a) => ({
			...a,
			connectionCount: countMap.get(a.agentId) ?? 0,
			activeConnectionCount: activeCountMap.get(a.agentId) ?? 0,
			clientCount: clientCountMap.get(a.agentId)?.size ?? 0,
			behaviorCount: watcherCountMap.get(a.agentId) ?? 0,
			userCount: userCountMap.get(a.agentId) ?? 0,
			platforms: platformsMap.get(a.agentId) ?? [],
			providers: providersMap.get(a.agentId) ?? [],
			status: (activeCountMap.get(a.agentId) ?? 0) > 0 ? "active" : "idle",
		})),
	});
});

