routes.delete("/:agentId", async (c) => {
	const denied = requireSessionOrAdminPat(c);
	if (denied) return denied;
	const { agentId } = c.req.param();

	if (!(await configStore.hasAgent(agentId))) {
		return c.json({ error: "Agent not found" }, 404);
