/**
 * Resolve a clicked activity/notification href into a structured peek
 * destination so the pane can mount the right shared content component. The
 * dedicated pages parse the same strings from their own URLs.
 *
 * Peekable destinations render their dedicated-page content component inline in
 * the pane (behavior runs, memory events/approvals). Connector detail is a full
 * management surface and doesn't fit a 460px pane, so it navigates normally
 * (the caller falls back to navigate() when this returns null).
 */
export type PeekDestination =
	| {
			kind: "behavior";
			owner: string;
			agentId: string;
			behaviorId: string;
			view?: "activity" | "definition";
			runId?: number;
	  }
	| {
			kind: "memory";
			owner: string;
			runId: number;
	  }
	| {
			kind: "memory";
			owner: string;
			runIds: number[];
	  }
	| {
			kind: "memory";
			owner: string;
			contentIds: number[];
	  };

const SEG = "[^/]+";

const BEHAVIOR_RE = new RegExp(
	`^/(${SEG})/agents/(${SEG})/behaviors/(${SEG})/?$`,
);

// Run permalinks live on /activity now; stored notification hrefs from before
// the Activity/Memory split still say /memory, so both shapes stay peekable.
const RUN_STREAM_RE = new RegExp(`^/(${SEG})/(?:activity|memory)/?$`);

export function parsePeekHref(href: string): PeekDestination | null {
	const { pathname, search } = parseAppHref(href);

	const m = pathname.match(BEHAVIOR_RE);
	if (m) {
		const [, owner, agentId, behaviorId] = m;
		const view =
			search?.view === "activity" || search?.view === "definition"
				? search.view
				: undefined;
		const runId = parseRunId(search?.run_id);
		return { kind: "behavior", owner, agentId, behaviorId, view, runId };
	}

	const mm = pathname.match(RUN_STREAM_RE);
	if (mm) {
		const [, owner] = mm;
		const runIds = parseIdList(search?.run_ids);
		if (runIds?.length === 1) {
			return { kind: "memory", owner, runId: runIds[0] };
		}
		if (runIds && runIds.length > 1) {
			return { kind: "memory", owner, runIds };
		}
		const contentIds = parseIdList(search?.content_ids);
		if (contentIds) return { kind: "memory", owner, contentIds };
		return null;
	}

	return null;
}

function parseIdList(value: string | undefined): number[] | null {
	if (!value) return null;
	const parts = value.split(",");
	if (parts.length === 0 || parts.length > 50) return null;
	const ids = parts.map((part) => parseRunId(part.trim()));
	return ids.every((id): id is number => id != null) ? ids : null;
}

function parseRunId(value: string | undefined): number | undefined {
	if (value == null || value === "") return undefined;
	const n = Number(value);
	return Number.isFinite(n) && n > 0 ? n : undefined;
}

