/// One-CLI-at-a-time queue for behavior runs. The Mac app has only one user
/// in the loop and can't realistically interleave multiple long-running
/// CLI spawns; serialize them. Incoming runs queue up to depth 5; deeper
/// than that the dispatcher refuses (we still post a completion-with-error
/// to the server so the run row doesn't sit `running` forever).
///
/// Lifecycle: `dispatch(job:client:workerId:)` returns when the job has
/// been processed end-to-end (executor spawned, completion posted). The
/// caller's poll loop should `await` it before pulling the next job.
@MainActor
final class BehaviorDispatcher {
    static let shared = BehaviorDispatcher()

    /// Fallback per-run timeout when a behavior sets no
    /// `execution_config.timeout_seconds`. A full agentic CLI loop routinely
    /// runs longer than a minute, so the floor is generous; per-behavior
    /// overrides (any positive value) win. Still bounded so a hung CLI can't
    /// wedge the serialized one-at-a-time queue indefinitely.
    static let defaultTimeout: TimeInterval = 600

    /// Maximum number of jobs waiting at once. We refuse-and-complete
    /// beyond this so we don't unboundedly buffer prompts on a stuck
    /// machine.
    static let maxQueueDepth = 5

    /// How often to heartbeat a run while its CLI executes. The server's
    /// stale-run sweeper reaps a heartbeating behavior run that goes silent
    /// for >3min (`BEHAVIOR_RUN_HEARTBEAT_STALE_INTERVAL`), so beating every
    /// 30s leaves ~4 missed beats of slack before a live turn could be
    /// mistaken for an abandoned one.
    static let heartbeatInterval: TimeInterval = 30

    private var executorsByKind: [AgentKind: LocalAgentExecutor]
    private var inFlight = 0
    private var queueDepth = 0

    /// Runs this device has claimed and not yet reported on — executing now, or
    /// queued behind the one that is. Read by the updater's idle gate: a claim
    /// outlives the process, so terminating here strands the run on the server
    /// until its heartbeat goes stale. Counts the queue too, because a queued
    /// job is already claimed — it is waiting on `inFlight`, not on the server.
    var claimedRunCount: Int { max(inFlight, queueDepth) }

    init(
        executors: [LocalAgentExecutor] = [
            ClaudeCodeExecutor(),
            AgyPrintExecutor(),
        ]
    ) {
        var byKind: [AgentKind: LocalAgentExecutor] = [:]
        for ex in executors { byKind[ex.agentKind] = ex }
        self.executorsByKind = byKind
    }

    /// Resolve the CLI to spawn for this job. `agent_kind` on the payload
    /// wins; falls back to the user's default agent in `UserDefaults`
    /// (`lobu.defaultAgent`, set from the menubar — see #797). Returns
    /// `nil` when neither source yields a registered executor; the
    /// dispatcher then reports completion-with-error so the server can
    /// surface the misconfiguration.
    func selectExecutor(for payload: BehaviorPayload) -> LocalAgentExecutor? {
        if let raw = payload.behavior.agent_kind,
           let kind = AgentKind(rawValue: raw),
           let ex = executorsByKind[kind] {
            return ex
        }
        if let fallback = LobuDefaultAgentSetting.current,
           let ex = executorsByKind[fallback] {
            return ex
        }
        return nil
    }

    /// Run one behavior job to completion. Spawns a CLI subprocess via the
    /// selected `LocalAgentExecutor`, posts the result back via
    /// `LobuClient.completeBehaviorRun`. The poll loop should await this.
    func dispatch(job: BehaviorJob, client: WorkerClient, workerId: String) async {
        if queueDepth >= Self.maxQueueDepth {
            await completeWithError(
                client: client,
                workerId: workerId,
                runId: job.run_id,
                error: BehaviorDispatchError.queueFull.errorDescription ?? "queue full",
                durationMs: 0,
                exitReason: "error_message"
            )
            return
        }
        queueDepth += 1
        defer { queueDepth -= 1 }

        // Serialize execution: one CLI spawn per device at a time.
        while inFlight > 0 {
            try? await Task.sleep(nanoseconds: 250_000_000)
        }
        inFlight += 1
        defer { inFlight -= 1 }

        guard let executor = selectExecutor(for: job.payload) else {
            let kind = job.payload.behavior.agent_kind ?? "(unset)"
            await completeWithError(
                client: client,
                workerId: workerId,
                runId: job.run_id,
            .split(separator: ":")
            .map(String.init)
        dirs.append("\(NSHomeDirectory())/.bun/bin")
        dirs.append("\(NSHomeDirectory())/.local/bin")
        dirs.append("/opt/homebrew/bin")
        dirs.append("/usr/local/bin")
        dirs.append("/usr/bin")
        return dirs
    }

    /// Walk `dirs` looking for an executable file named `binary`. First hit
    /// wins. Returns the absolute path or `nil`.
    static func locate(binary: String, in dirs: [String]) -> String? {
        let fm = FileManager.default
        for dir in dirs where !dir.isEmpty {
            let candidate = "\(dir)/\(binary)"
            if fm.isExecutableFile(atPath: candidate) { return candidate }
        }
        return nil
    }

    /// Exec `<binary> --version` and return the first non-empty line of
    /// combined stdout/stderr. Best-effort: any failure (non-zero exit,
    /// signal, missing pipes, exec error, slow process) collapses to `nil` so
    /// the caller still records the binary as detected. We never throw.
    ///
    /// A 2-second wall clock is plenty for a `--version` call; anything
    /// longer means the binary's misbehaving and we'd rather show "no
    /// version" than block the popover.
    private static func captureVersion(binaryPath: String) -> String? {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: binaryPath)
        process.arguments = ["--version"]
        let pipe = Pipe()
        process.standardOutput = pipe
        process.standardError = pipe
        do {
            try process.run()
        } catch {
            return nil
        }
        // Bound the wait. `waitUntilExit` is blocking; gate it on a deadline
        // and SIGKILL on overrun so a hung binary can't lock the actor.
        let deadline = Date().addingTimeInterval(2.0)
        while process.isRunning && Date() < deadline {
            Thread.sleep(forTimeInterval: 0.05)
        }
        if process.isRunning {
            process.terminate()
            // Give it a moment to clean up before we return.
            Thread.sleep(forTimeInterval: 0.05)
            if process.isRunning { kill(process.processIdentifier, SIGKILL) }
            return nil
        }
        let data = (try? pipe.fileHandleForReading.readToEnd()) ?? Data()
        guard let raw = String(data: data, encoding: .utf8) else { return nil }
        let trimmed = raw
            .split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .first(where: { !$0.isEmpty })
        return trimmed
    }
}

/// `UserDefaults` key for the user's preferred default agent. The Behavior
/// executor (`BehaviorDispatcher`, lobu#798) reads it to pick which CLI to
/// spawn when a Behavior fires without an explicit `agent_kind` override.
/// Lives here so the menubar row and the executor agree on the key name.
enum LobuDefaultAgentSetting {
    static let key = "lobu.defaultAgent"

    static var current: AgentKind? {
        guard let raw = UserDefaults.standard.string(forKey: key) else { return nil }
        return AgentKind(rawValue: raw)
    }

    static func set(_ kind: AgentKind?) {
        if let kind {
            UserDefaults.standard.set(kind.rawValue, forKey: key)
        } else {
            UserDefaults.standard.removeObject(forKey: key)
        }
    }
}
import AppKit
import SwiftUI

/// The popover shown when the user clicks the menu bar icon. Layout (top → bottom):
///   1. Header — "Lobu" title with sync toggle, status line below
///   2. User row — avatar + name + email (or "Not signed in") + context picker
///   3. Search bar — small TextField; results take over the body when active
///   4. Inbox — unread + recent notifications
///   5. Connected agents — locally-detected CLI agents + default-agent picker
///   6. Sign-in section — only when signed out
///   7. Footer — Open Owletto / Sign out / Quit / Updates
///
/// Device sources, Behaviors, and connectors are all managed on the web
/// at `state.baseURL` (`app.lobu.ai` for Lobu Cloud, `localhost:8787` for the
/// embedded server) — the menu bar is status-only. "Open Owletto" in the
/// footer takes the user there.
struct MenuBarContent: View {
    @ObservedObject var state: AppState
    // Disclosure toggles, persisted via @AppStorage so user collapses
    // survive restart. Default collapsed for all sections — auto-expand
    // makes the popover feel like an alert tray.
    @AppStorage("ui.connectedAgentsExpanded") private var connectedAgentsExpanded = false
    @AppStorage("ui.inboxExpanded") private var inboxExpanded = false
    // Defaults closed: once permissions are set they never need looking at, and
    // the header still reports a count when something is off.
    @AppStorage("ui.permissionsExpanded") private var permissionsExpanded = false
    // Context picker visibility persists across launches (like the other
    // disclosures) and defaults to open, so the selector is always one glance
    // away and you can see all contexts without hunting for it. Sign-in/out no
    // longer overrides this; a connection error still force-expands it below.
    @AppStorage("ui.contextPickerExpanded") private var accountExpanded = true
    @State private var errorDetailsExpanded = false
    @State private var addContextExpanded = false
    @State private var emailLoginExpanded = false
    @State private var emailLoginDraft = ""
    @State private var newContextName = ""
    @State private var newContextApiUrl = ""
    @State private var newContextLifecycle = "external"
    @State private var newContextError: String?
    /// Bumped after a grant attempt so the permission rows re-probe TCC.
    @State private var permissionsRefreshToken = 0
    @FocusState private var searchFocused: Bool

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            header
            sectionDivider

            // One unified user/context row regardless of sign-in state.
            // Signed in → avatar + name + email; signed out → placeholder
            // avatar + "Not signed in" copy. Either way the context name
            // shows in the subtitle so switching contexts doesn't shift
            // the layout. Always visible — local-init sessions carry a real
            // user/org now, and the context picker must stay one glance away.
            userRow
            sectionDivider
            if state.credentials != nil {
                searchBar
                if !state.searchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    sectionDivider
                    searchResultsSection
                } else {
                    if !state.notifications.isEmpty {
                        sectionDivider
                        notificationsSection
                    }
                }
            }

            // Connected CLI agents — the "default agent" pick is the main
            // decision on a fresh launch. Always visible (signed-in or not) so
            // the user can see the install links before they sign in.
            sectionDivider
            connectedAgentsDisclosure

            // OS permissions + login item — collapsible; header carries a count
            // of what's off so a collapsed section still flags a problem.
            sectionDivider
            permissionsSection

            sectionDivider
            footerRow
        }
        .padding(.horizontal, 8)
        .padding(.vertical, 8)
        .frame(width: 340)
        .onAppear {
            permissionsRefreshToken &+= 1
            Task {
                await DevicePermissionKind.refreshNotificationStatus()
                await MainActor.run { permissionsRefreshToken &+= 1 }
            }
        }
    }

    private var sectionDivider: some View {
        Divider().padding(.vertical, 6).padding(.horizontal, 6)
    }


    // -------------------------------------------------------------------------
    // MARK: 1. Header
    // -------------------------------------------------------------------------

    private var header: some View {
        VStack(alignment: .leading, spacing: 2) {
            HStack(alignment: .firstTextBaseline, spacing: 6) {
                Text("Owletto")
                    .font(.headline)
                Text(Host.current().localizedName ?? "This Mac")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Spacer()
                if state.credentials != nil {
                    Toggle("", isOn: Binding(
